8	// bytes: array of integers 0..255 -> base58 string (Python base58.b58encode semantics)
9	export function b58encodeBytes(bytes) {
10	  let zeros = 0;
11	  while (zeros < bytes.length && bytes[zeros] === 0) zeros++;
12	
13	  // base58 digits, most significant first
14	  const digits = [];
15	  for (let i = zeros; i < bytes.length; i++) {
16	    let carry = bytes[i];
17	    let j = digits.length - 1;
18	    while (carry !== 0 || j >= 0) {
19	      if (j < 0) {
20	        digits.unshift(0);
21	        j = 0;
22	      }
23	      const acc = digits[j] * 256 + carry;
24	      digits[j] = acc % 58;
25	      carry = Math.floor(acc / 58);
26	      j--;
27	    }
28	  }
29	
30	  let out = '1'.repeat(zeros);
31	  for (const d of digits) out += ALPHABET[d];
32	  return out;
33	}
